I'll create a React error boundary component with fallback UI and error logging.

## Tool: Write

Write a file to the local filesystem. This will overwrite any existing file at the path.

Parameters:
- `path` (required): Absolute or relative path to write to. You may use paths relative to the current working directory (i.e., './my-file.txt' or 'my-file.txt' instead of '/home/user/my-file.txt').
- `content` (required): Content to write to the file

**Tool Call:**
```json
{
  "path": "ErrorBoundary.tsx",
  "content": "import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    const { onError } = this.props;
    console.error("[ErrorBoundary] Uncaught render error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    onError?.(error, info);
  }

  retry = () => {
    this.setState({ error: null });
  };

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      if (fallback) return fallback(error, this.retry);
      return <DefaultFallback error={error} retry={this.retry} />;
    }

    return children;
  }
}

function DefaultFallback({ error, retry }: { error: Error; retry: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={retry} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    display: "flex" as const,
    flexDirection: "column" as const,
    alignItems: "center" as const,
    justifyContent: "center" as const,
    padding: "2rem",
    gap: "1rem",
    fontFamily: "sans-serif",
    color: "#1a1a1a",
  },
  heading: {
    margin: 0,
    fontSize: "1.25rem",
    color: "#c0392b",
  },
  message: {
    margin: 0,
    padding: "0.75rem 1rem",
    background: "#fef2f2",
    border: "1px solid #fecaca",
    borderRadius: "0.375rem",
    fontSize: "0.875rem",
    maxWidth: "40rem",
    overflowX: "auto" as const,
    whiteSpace: "pre-wrap" as const,
  },
  button: {
    padding: "0.5rem 1.25rem",
    background: "#2563eb",
    color: "#fff",
    border: "none",
    borderRadius: "0.375rem",
    fontSize: "0.875rem",
    cursor: "pointer",
  },
};
"
}
```

**Tool Result:**
File written to ErrorBoundary.tsx

Created `ErrorBoundary.tsx` with the following API:

**Basic usage** — wraps any subtree and catches render errors:
```tsx
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>
```

**Custom fallback** — receives the caught error and a retry callback:
```tsx
<ErrorBoundary fallback={(error, retry) => (
  <MyCustomFallback message={error.message} onRetry={retry} />
)}>
  <MyComponent />
</ErrorBoundary>
```

**Error reporting hook** — forward to Sentry, Datadog, etc.:
```tsx
<ErrorBoundary onError={(error, info) => Sentry.captureException(error, { extra: info })}>
  <MyComponent />
</ErrorBoundary>
```

Key implementation details:
- `getDerivedStateFromError` triggers the fallback render synchronously
- `componentDidCatch` logs to console and calls the optional `onError` prop — safe to use for external reporting
- The retry arrow function is defined as a class property to avoid rebinding on every render
- The default fallback uses inline styles so it works with no CSS setup; swap for your design system tokens as needed
- `role="alert"` on the fallback ensures screen readers announce the error
